"""A stand-in for Stage A0 (bite check, scratch only): runs the real ``gov`` with A0 wrapped so that it does what
Interface I1/I2 say, with one flaw chosen by STANDIN_FLAW. Never in the ticket's paths."""
import os
import sys
from pathlib import Path

sys.path.insert(0, os.environ["STANDIN_SRC"])
FLAW = os.environ.get("STANDIN_FLAW", "")

import yaml  # noqa: E402

from gov.adopt import project as proj, safety, stages  # noqa: E402
from gov.guard import install  # noqa: E402
from gov.tasks import tickets  # noqa: E402

ROSTER = "governance/project/roster.yaml"
EXTRA_FILES, EXTRA_DATA = {}, {}
orig_setup, orig_a0, orig_finish = safety.setup, stages.a0, stages.Run.finish


def setup(root):
    return {**orig_setup(root), **EXTRA_FILES}


def finish(self, data, extra=None, **result):
    if self.stage == "A0" and EXTRA_DATA:
        data = {**data, **EXTRA_DATA}
    return orig_finish(self, data, extra, **result)


def a0(run):
    root = run.root
    path = root / ROSTER
    text = path.read_text(encoding="utf-8") if path.is_file() else None
    existing, why = install.coordination_ticket(root)
    if existing is not None and FLAW != "i_creates_new":
        return orig_a0(run)                                   # I2 (i): keep it, create nothing
    if not (root / tickets.TK_REL).exists():
        if FLAW == "tk_missing_leaves_record":
            orig_a0(run)
        raise proj.refuse("TK_MISSING", f"the vendored tk ({tickets.TK_REL}) is missing: nothing is written")
    title = f"{root.name} coordination" if FLAW != "wrong_title" else f"coordination of {root.name}"
    ticket = tickets.create(root, title)
    tfile = root / ".tickets" / f"{ticket}.md"
    body = tfile.read_text(encoding="utf-8")
    if FLAW != "no_class":
        lines = body.split("\n")
        lines.insert(lines.index("---", 1), "class: coordination")
        body = "\n".join(lines)
    if FLAW == "ticket_uncommitted":
        tfile.write_text(body, encoding="utf-8")
    else:
        tfile.unlink()
        EXTRA_FILES[f".tickets/{ticket}.md"] = body
    value = "DAEO-nope" if FLAW == "key_names_missing" else ticket
    if FLAW != "no_roster_key":
        if text is None:
            EXTRA_FILES[ROSTER] = f"coordination_ticket: {value}\n"
        elif FLAW == "rewrites_roster":
            data = yaml.safe_load(text) or {}
            data["coordination_ticket"] = value
            EXTRA_FILES[ROSTER] = yaml.safe_dump(data, sort_keys=False)
        else:
            EXTRA_FILES[ROSTER] = text + ("" if text.endswith("\n") else "\n") + f"coordination_ticket: {value}\n"
    if FLAW != "record_silent":
        EXTRA_DATA.update({"coordination_ticket": ticket, "roster": ROSTER})
    return orig_a0(run)


safety.setup = setup
stages.Run.finish = finish
stages.a0 = a0
stages.STAGE["A0"] = a0

from gov.cli.main import main  # noqa: E402

sys.exit(main())

"""A pytest plugin for the bite checks (scratch only): STANDIN_FLAW selects an A0 stand-in (run through
``standin_gov.py`` instead of the real ``gov``); STANDIN_TEXT selects a refusal text stand-in put in place of the
hook's reason. The suite itself is not touched."""
import dataclasses
import os
import subprocess
import sys
from pathlib import Path

import pytest

HERE = Path(__file__).resolve().parent
FLAW = os.environ.get("STANDIN_FLAW")
TEXT = os.environ.get("STANDIN_TEXT")
OLD = "(set at adoption)"


def _text(reason):
    if TEXT == "good":
        return reason.replace(OLD, "(GOV_TICKET of the CTO's session must name it; `gov adopt --lite --stage A0` writes the key)")
    if TEXT == "no_variable":
        return reason.replace(OLD, "(adoption writes the key)")
    if TEXT == "claims_set":
        return reason.replace(OLD, "(GOV_TICKET names it; set at adoption)")
    if TEXT == "lying_value":
        return reason.replace(OLD, "(GOV_TICKET names it)") + " The key names the coordination ticket."
    if TEXT == "no_how":
        return "installs are refused in every session: GOV_TICKET names no coordination ticket"
    return reason


@pytest.fixture(autouse=True, scope="session")
def _standins():
    import w2_113_support as support
    w110, w23 = support.w110, support.w23
    if FLAW is not None:
        def run_a0(project, box):
            env = w23.environment(box, STANDIN_FLAW=FLAW, STANDIN_SRC=str(support.REPO_ROOT / "src"))
            done = subprocess.run([sys.executable, str(HERE / "standin_gov.py"), "adopt", "--lite", "--stage", "A0",
                                   "--json", "--session", support.ADOPTER], cwd=str(project), env=env,
                                  capture_output=True, text=True, stdin=subprocess.DEVNULL, timeout=180)
            return w23.Done(("adopt", "--lite", "--stage", "A0"), done.returncode, done.stdout, done.stderr)
        support.run_a0 = run_a0
    if TEXT is not None:
        real = w110.call

        def call(project, settings, sandbox, session, command, mode="default"):
            answer = real(project, settings, sandbox, session, command, mode)
            if TEXT == "asks" and answer.decision == "deny":
                return dataclasses.replace(answer, decision="ask")
            if answer.decision == "deny":
                return dataclasses.replace(answer, reason=_text(answer.reason))
            return answer
        w110.call = call
    yield
